      "path": "native/macos-helper/Sources/DSHComputerUseCore/Agent/ComputerUseAgent.swift",
      "content": "import Foundation\n\n/// Routes protocol requests to the underlying services and produces responses.\npublic final class ComputerUseAgent {\n    /// Integer wire protocol version.\n    public static let protocolVersion = 1\n    /// Helper's own semver.\n    public static let helperVersion = \"0.3.0\"\n    public static let appName = \"DSHComputerUse\"\n\n    public let observer = DesktopObserver()\n    public let controller: DesktopController\n    public let ocr = VisionOCRService()\n    public let screenCapture = ScreenCaptureManager()\n    public let cancellation = CancellationRegistry()\n\n    public var socketPath: String?\n\n    public init() {\n        controller = DesktopController(cancellation: cancellation)\n    }\n\n    public func handle(request: Request) -> Response {\n        do {\n            let result = try handleMethod(request.method, params: request.params, requestId: request.id)\n            cancellation.clear(request.id)\n            return .success(id: request.id, result: result)\n        } catch {\n            cancellation.clear(request.id)\n            let payload = errorPayload(for: error)\n            return .failure(id: request.id, error: payload)\n        }\n    }\n\n    private func handleMethod(_ method: String, params: JSONValue, requestId: String) throws -> JSONValue {\n        switch method {\n        case \"handshake\":\n            return try CodableBridge.toJSONValue(HandshakeResult(\n                protocolVersion: Self.protocolVersion,\n                helperVersion: Self.helperVersion,\n                appName: Self.appName,\n                platform: \"macos\",\n                capabilities: capabilities()\n            ))\n\n        case \"status\":\n            let capture = screenCapture.captureInfo()\n            return try CodableBridge.toJSONValue(StatusReport(\n                permissions: Permissions.report,\n                mainDisplayCount: capture.mainDisplayCount,\n                socketPath: socketPath,\n                macosVersion: ProcessInfo.processInfo.operatingSystemVersionString,\n                architecture: architectureName()\n            ))\n\n        case \"observeDesktop\":\n            let observeParams: ObserveParams = (try? CodableBridge.fromJSONValue(params))\n                ?? ObserveParams()\n            return try CodableBridge.toJSONValue(observer.observe(params: observeParams))\n\n        case \"performDesktop\":\n            let action: DesktopAction = try CodableBridge.fromJSONValue(params)\n            let result = try controller.perform(action, requestId: requestId)\n            return try CodableBridge.toJSONValue(result)\n\n        case \"ocrFile\":\n            let request: OCRFileRequest = try CodableBridge.fromJSONValue(params)\n            let result = try ocr.recognize(imageURL: URL(fileURLWithPath: request.path), languages: request.languages ?? [])\n            return try CodableBridge.toJSONValue(result)\n\n        case \"shutdown\":\n            DispatchQueue.main.asyncAfter(deadline: .now() + 0.1) {\n                exit(0)\n            }\n            return try CodableBridge.toJSONValue(ActionResult(\n                performed: true,\n                action: \"shutdown\",\n                method: \"process\"\n            ))\n\n        case \"cancel\":\n            // Best-effort cancellation of an in-flight request id. The driver\n            // sends `{ requestId: \"<id of the request to cancel>\" }`.\n            if let dict = params.dictionary,\n               let target = dict[\"requestId\"]?.stringValue ?? dict[\"id\"]?.stringValue {\n                cancellation.cancel(target)\n            }\n            return try CodableBridge.toJSONValue(ActionResult(\n                performed: true,\n                action: \"cancel\",\n                method: \"registry\"\n            ))\n\n        default:\n            throw AgentError.unknownMethod(\"Unknown method: \\(method)\")\n        }\n    }\n\n    private func errorPayload(for error: Error) -> JSONValue {\n        let payload: ErrorPayload\n        if let agentError = error as? AgentError {\n            payload = ErrorPayload(code: agentError.code, message: agentError.message)\n        } else if let decoding = error as? DecodingError {\n            payload = ErrorPayload(code: \"INVALID_PARAMS\", message: String(describing: decoding))\n        } else {\n            payload = ErrorPayload(code: \"INTERNAL_ERROR\", message: error.localizedDescription)\n        }\n        return (try? CodableBridge.toJSONValue(payload)) ?? .object([\n            \"code\": .string(payload.code),\n            \"message\": .string(payload.message),\n        ])\n    }\n\n    private func capabilities() -> [String] {\n        var result = [\n            \"handshake\", \"status\", \"observeDesktop\", \"performDesktop\", \"ocrFile\", \"shutdown\",\n            \"ax-input\", \"coregraphics-input\", \"coregraphics-pid-input\", \"vision-ocr\",\n            \"screen-capture\", \"window-capture\", \"virtual-cursor\",\n        ]\n        if SkyLightBridge.canPostToProcess { result.append(\"skylight-input\") }\n        if SkyLightBridge.canFocusWithoutRaise { result.append(\"skylight-focus-without-raise\") }\n        return result\n    }\n\n    private func architectureName() -> String {\n        #if arch(arm64)\n        return \"arm64\"\n        #elseif arch(x86_64)\n        return \"x86_64\"\n        #else\n        return \"unknown\"\n        #endif\n    }\n}\n"
    },
    {
      "path": "documentation/distribution.md",
      "content": "# macOS distribution\n\nOfficial releases are open-source builds delivered outside the Mac App Store as Developer ID signed and Apple-notarized Universal 2 DMGs.\n\n## Local installer\n\n```bash\npnpm install\npnpm run build\npnpm run package:dmg\n```\n\nThis creates an ad-hoc or development-signed installer under `release/`. It is suitable for local verification, not public distribution.\n\nUse a single architecture for faster development:\n\n```bash\nCOMPUTER_USE_ARCHS=arm64 pnpm run build\n```\n\n`package:dmg` deliberately rejects non-Universal app bundles.\n\n## Install a Developer ID certificate\n\nYou need the `Developer ID Application` certificate for the Apple Developer Program team that will publish the App. An Account Holder or Admin can create it; another team role needs the **Access to Certificates, Identifiers & Profiles** permission.\n\n### Xcode, recommended\n\n1. Open **Xcode > Settings > Accounts** and add the Apple ID enrolled in the team.\n2. Select the team, open **Manage Certificates**, select `+`, then choose **Developer ID Application**.\n3. Xcode creates the private key in the login keychain and installs the matching certificate.\n\n### Apple Developer website\n\nUse this route when Xcode cannot create the certificate:\n\n1. Open **Keychain Access > Certificate Assistant > Request a Certificate From a Certificate Authority**.\n2. Enter the Apple ID email and a descriptive common name, choose **Saved to disk**, and save the CSR.\n3. Open [Certificates, Identifiers & Profiles](https://developer.apple.com/account/resources/certificates/add), choose **Developer ID Application**, and upload the CSR.\n4. Download the `.cer` file and double-click it to import it into the login keychain.\n5. In **Keychain Access > My Certificates**, expand the certificate and confirm that a private key appears underneath it.\n\nA `.cer` file does not contain the private key. If no private key appears, the CSR was created on another Mac or the key was deleted; create a new certificate/CSR rather than trying to sign with the `.cer` alone.\n\nVerify the installed identity:\n\n```bash\nsecurity find-identity -v -p codesigning\n```\n\nThe output must include a valid line beginning with `Developer ID Application:`. Keep the private key in the login keychain; do not commit or upload it.\n\n### Export for GitHub Actions\n\nIn **Keychain Access > My Certificates**, right-click the Developer ID certificate, choose **Export**, select `.p12`, and set a strong temporary password. Encode it for the `MACOS_CERTIFICATE_P12` secret:\n\n```bash\nbase64 -i DeveloperIDApplication.p12 | pbcopy\n```\n\nThe P12 password becomes `MACOS_CERTIFICATE_PASSWORD`. Delete unencrypted copies and securely archive the original P12 after the CI secret is configured.\n\n## Notarization and release\n\nAfter installing the certificate, store notarization credentials in a keychain profile:\n\n```bash\nxcrun notarytool store-credentials dsh-computer-use-notary \\\n  --apple-id 'release@example.com' \\\n  --team-id 'TEAMID' \\\n  --password 'app-specific-password'\n\nCOMPUTER_USE_CODESIGN_IDENTITY='Developer ID Application: Example (TEAMID)' \\\n  pnpm run build\n\nCOMPUTER_USE_CODESIGN_IDENTITY='Developer ID Application: Example (TEAMID)' \\\nNOTARYTOOL_PROFILE='dsh-computer-use-notary' \\\n  pnpm run release:macos\n```\n\nThe release script:\n\n1. verifies the nested app signature and both architectures;\n2. notarizes a ZIP and staples the App;\n3. creates a drag-to-Applications DMG;\n4. signs, notarizes, and staples the DMG;\n5. runs Gatekeeper assessment; and\n6. writes a SHA-256 checksum.\n\nApp Store sandboxing is intentionally not enabled. The full product uses private SkyLight APIs for background targeted input and is not eligible for Mac App Store review.\n\n## GitHub Actions secrets\n\nFor CI notarization, create a Team API key in **App Store Connect > Users and Access > Integrations > App Store Connect API**. Record the issuer ID and key ID, then download the `.p8` once; Apple does not offer a second download.\n\nThe tagged release workflow expects:\n\n| Secret | Purpose |\n| --- | --- |\n| `MACOS_CERTIFICATE_P12` | Base64 Developer ID Application certificate and private key |\n| `MACOS_CERTIFICATE_PASSWORD` | P12 password |\n| `MACOS_KEYCHAIN_PASSWORD` | Ephemeral CI keychain password |\n| `MACOS_CODESIGN_IDENTITY` | Full `Developer ID Application: ...` identity |\n| `APPLE_API_KEY_ID` | App Store Connect API key ID |\n| `APPLE_API_ISSUER_ID` | App Store Connect issuer ID |\n| `APPLE_API_KEY_P8` | P8 private key contents |\n| `HOMEBREW_TAP_DEPLOY_KEY` | SSH deploy key with write access only to `ZRui-C/homebrew-tap` |\n\nNever place these values in repository variables, source files, workflow logs, issue reports, or release assets.\n\n## User upgrade behavior\n\nReplacing the App in `/Applications` preserves the bundle ID and designated requirement. A release signed by the same Team ID normally retains TCC grants. Open the setup center after upgrading and select **Reinstall** to refresh the DSH file dependency, then restart the running DSH Host.\n\n## Homebrew Cask\n\nThe public Cask lives in [`ZRui-C/homebrew-tap`](https://github.com/ZRui-C/homebrew-tap) and installs the same signed, notarized DMG published in GitHub Releases:\n\n```bash\nbrew tap zrui-c/tap\nbrew trust zrui-c/tap\nbrew install --cask dsh-computer-use\n```\n\nAfter a tagged release publishes its DMG and checksum, the release workflow reads the generated SHA-256, updates `Casks/dsh-computer-use.rb`, and pushes the change with the dedicated `HOMEBREW_TAP_DEPLOY_KEY`. This deploy key has write access only to the Tap repository.\n\nDo not publish the native helper through npm or use an npm lifecycle script to copy an App into `/Applications`. The DMG remains the canonical release artifact; Homebrew is an installation and upgrade frontend for that artifact.\n"
    }
